import AVFoundation
import Observation

/// Plays Waybill's ambience and effects (all generated by `Synth`).
///
/// - Ambience: looping layers per region (wind, traffic, water, crickets at night) plus occasional calls
///   (birds, gulls, a distant horn). Day and night crossfade with the real clock.
/// - Effects: one short sound per game event (dispatch chime, upgrade pluck, contract stamp…).
/// The M1 iPad Pro has no haptics, so sound is the physical feedback.
@Observable
final class SoundEngine {
    var enabled: Bool = UserDefaults.standard.object(forKey: "soundOn") as? Bool ?? true {
        didSet {
            UserDefaults.standard.set(enabled, forKey: "soundOn")
            let mixer = engine.mainMixerNode, volume: Float = enabled ? 0.9 : 0
            audio.async { mixer.outputVolume = volume }
        }
    }

    /// Every call into the audio nodes after start-up runs here, in order. Setting a volume or restarting a player waits
    /// for the audio thread, which could hold up a frame by several milliseconds; off the main thread it costs nothing.
    @ObservationIgnored private let audio = DispatchQueue(label: "com.yorben.waybill.audio", qos: .userInitiated)
    /// Ambience volumes as faded every frame, and as last handed to the players (only real changes are sent).
    @ObservationIgnored private var levels: [String: Float] = [:]
    @ObservationIgnored private var sent: [String: Float] = [:]

    @ObservationIgnored private let engine = AVAudioEngine()
    @ObservationIgnored private let reverb = AVAudioUnitReverb()
    @ObservationIgnored private let fxBus = AVAudioMixerNode()
    @ObservationIgnored private var fxPlayers: [AVAudioPlayerNode] = []
    @ObservationIgnored private var nextPlayer = 0
    @ObservationIgnored private var buffers: [String: AVAudioPCMBuffer] = [:]
    @ObservationIgnored private var loops: [String: AVAudioPlayerNode] = [:]
    @ObservationIgnored private var beep = AVAudioPlayerNode()
    @ObservationIgnored private var ready = false
    /// All sounds are rendered and the engine runs.
    var isReady: Bool { ready }
    @ObservationIgnored private var region: RegionID = .riverside
    @ObservationIgnored private var callTimer: Double = 4
    @ObservationIgnored private var hornTimer: Double = 70
    @ObservationIgnored private var upgradeStep = 0
    @ObservationIgnored private var lastPlayed: [String: Double] = [:]
    @ObservationIgnored private var clock: Double = 0

    // MARK: Start

    func start(region: RegionID) {
        self.region = region
        guard !ready else { return }
        try? AVAudioSession.sharedInstance().setCategory(.ambient, mode: .default)
        try? AVAudioSession.sharedInstance().setActive(true)
        Task.detached(priority: .utility) {
            let samples = Self.makeSamples()
            await MainActor.run { self.finishStart(samples) }
        }
    }

    /// Render every sound once (takes a moment, so it runs in the background).
    nonisolated private static func makeSamples() -> [String: [Float]] {
        var s: [String: [Float]] = [
            "dispatch": Synth.dispatch(), "sparkle": Synth.sparkle(), "chord": Synth.chord(), "stamp": Synth.stamp(),
            "fanfare": Synth.fanfare(), "fail": Synth.fail(), "shimmer": Synth.shimmer(), "blip": Synth.blip(),
            "whoosh": Synth.whoosh(), "beep": Synth.reverseBeep(),
            "wind": Synth.wind(), "windStrong": Synth.wind(seconds: 10, strength: 1, seed: 99), "traffic": Synth.traffic(),
            "water": Synth.water(), "crickets": Synth.crickets(), "city": Synth.cityHum(),
            "shipHorn": Synth.horn(freqs: [98, 123.5], seconds: 2.4), "trainHorn": Synth.horn(freqs: [311.1, 392, 466.2], seconds: 1.6),
        ]
        for i in 0..<8 { s["up\(i)"] = Synth.upgrade(step: i) }
        for i in 0..<5 { s["bird\(i)"] = Synth.bird(seed: UInt32(100 + i * 37)) }
        for i in 0..<3 { s["gull\(i)"] = Synth.gull(seed: UInt32(300 + i * 17)) }
        return s
    }

    private func finishStart(_ samples: [String: [Float]]) {
        for (name, data) in samples { buffers[name] = Synth.buffer(data) }
        let format = Synth.format
        reverb.loadFactoryPreset(.mediumRoom)
        reverb.wetDryMix = 18
        engine.attach(reverb)
        engine.attach(fxBus)
        engine.connect(fxBus, to: reverb, format: format)
        engine.connect(reverb, to: engine.mainMixerNode, format: format)
        for _ in 0..<10 {
            let p = AVAudioPlayerNode()
            engine.attach(p)
            engine.connect(p, to: fxBus, format: format)
            fxPlayers.append(p)
        }
        for name in ["wind", "windStrong", "traffic", "water", "crickets", "city"] {
            let p = AVAudioPlayerNode()
            engine.attach(p)
            engine.connect(p, to: engine.mainMixerNode, format: format)
            p.volume = 0
            loops[name] = p
        }
        engine.attach(beep)
        engine.connect(beep, to: engine.mainMixerNode, format: format)
        beep.volume = 0
        engine.mainMixerNode.outputVolume = enabled ? 0.9 : 0
        engine.prepare()
        do { try engine.start() } catch { NSLog("[Waybill] audio failed to start: %@", "\(error)"); return }
        for (name, p) in loops {
            if let b = buffers[name] { p.scheduleBuffer(b, at: nil, options: .loops); p.play() }
        }
        if let b = buffers["beep"] { beep.scheduleBuffer(b, at: nil, options: .loops); beep.play() }
        ready = true
    }

    /// App back in the foreground.
    func resume() {
        guard ready else { return }
        let engine = engine, loops = loops, buffers = buffers, beep = beep
        audio.async {
            guard !engine.isRunning else { return }
            try? AVAudioSession.sharedInstance().setActive(true)
            try? engine.start()
            for (name, p) in loops where !p.isPlaying { if let b = buffers[name] { p.scheduleBuffer(b, at: nil, options: .loops); p.play() } }
            if !beep.isPlaying, let b = buffers["beep"] { beep.scheduleBuffer(b, at: nil, options: .loops); beep.play() }
        }
    }

    func setRegion(_ id: RegionID) { region = id }

    // MARK: Effects

    /// Play a one-shot effect. Very frequent sounds (auto-dispatch) are thinned out.
    func play(_ name: String, volume: Float = 1, minGap: Double = 0) {
        guard ready, enabled, let buffer = buffers[name] else { return }
        if minGap > 0, let last = lastPlayed[name], clock - last < minGap { return }
        lastPlayed[name] = clock
        let p = fxPlayers[nextPlayer]
        nextPlayer = (nextPlayer + 1) % fxPlayers.count
        audio.async {
            p.stop()
            p.volume = volume
            p.scheduleBuffer(buffer, at: nil, options: [])
            p.play()
        }
    }

    /// Sounds for game events.
    func handle(_ event: GameModel.Event) {
        switch event {
        case .dispatched: play("dispatch", volume: 0.5, minGap: 1.2)
        case .upgraded:
            play("up\(upgradeStep % 8)", volume: 0.55)
            upgradeStep += 1
        case .milestone, .unlocked: play("sparkle", volume: 0.6)
        case .hired: play("chord", volume: 0.6)
        case .contractAccepted: play("stamp", volume: 0.7)
        case .contractFinished(_, let success): play(success ? "fanfare" : "fail", volume: 0.6)
        case .researchStarted: play("blip", volume: 0.5)
        case .researchDone: play("shimmer", volume: 0.6)
        case .constructionStarted: play("stamp", volume: 0.6)
        case .constructionDone: play("fanfare", volume: 0.6)
        case .rush: play("whoosh", volume: 0.6)
        case .regionChanged(let id): region = id; play("shimmer", volume: 0.5)
        case .caughtUp: break
        }
    }

    // MARK: Ambience (called every frame by the world)

    /// - night: 0 day … 1 night. - beep: 0…1 how loud a nearby reversing truck is. - zoom: 0 close … 1 far.
    func update(dt: Double, night: Float, beep beepLevel: Float, zoom: Float) {
        clock += dt
        guard ready else { return }
        let day = 1 - night
        let near = 1 - zoom * 0.5
        var target: [String: Float] = ["wind": 0, "windStrong": 0, "traffic": 0, "water": 0, "crickets": 0, "city": 0]
        switch region {
        case .riverside:
            target["wind"] = 0.16
            target["traffic"] = 0.11 * (0.4 + 0.6 * day)
            target["water"] = 0.1 * near
            target["crickets"] = 0.13 * night
        case .harbour:
            target["wind"] = 0.2
            target["water"] = 0.22 * near
            target["traffic"] = 0.09
            target["crickets"] = 0.05 * night
        case .granite:
            target["windStrong"] = 0.26
            target["wind"] = 0.08
            target["crickets"] = 0.06 * night
        case .metro:
            target["city"] = 0.2
            target["traffic"] = 0.15 * (0.5 + 0.5 * day)
            target["wind"] = 0.05
        case .orbit:
            target["wind"] = 0.22
            target["traffic"] = 0.05
            target["crickets"] = 0.08 * night
        }
        let k = Float(1 - exp(-dt * 1.5))
        for name in loops.keys {
            let t = target[name] ?? 0
            let v = levels[name] ?? 0
            levels[name] = v + (t - v) * k
        }
        let b = levels["beep"] ?? 0
        levels["beep"] = b + (beepLevel * 0.16 - b) * Float(1 - exp(-dt * 8))
        // Hand over only changes you could hear (and silence exactly), off the main thread
        var changes: [(AVAudioPlayerNode, Float)] = []
        for (name, v) in levels {
            let last = sent[name] ?? 0
            guard abs(v - last) > 0.0005 || (v < 0.0005 && last != 0) else { continue }
            let value = v < 0.0005 ? 0 : v
            sent[name] = value
            if let p = name == "beep" ? beep : loops[name] { changes.append((p, value)) }
        }
        if !changes.isEmpty { audio.async { for (p, v) in changes { p.volume = v } } }

        // Occasional calls: birds by day (gulls in the harbour), a horn now and then
        callTimer -= dt
        if callTimer <= 0 {
            callTimer = Double.random(in: 3...9)
            switch region {
            case .riverside, .granite:
                if day > 0.4 { play("bird\(Int.random(in: 0..<5))", volume: Float.random(in: 0.08...0.18) * day * near) }
            case .harbour:
                if day > 0.3 { play("gull\(Int.random(in: 0..<3))", volume: Float.random(in: 0.08...0.16) * near) }
            default: break
            }
        }
        hornTimer -= dt
        if hornTimer <= 0 {
            hornTimer = Double.random(in: 70...140)
            if region == .harbour { play("shipHorn", volume: 0.18) }
            if region == .granite { play("trainHorn", volume: 0.14) }
        }
    }
}
